module garland_minimizer(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [5:0] n,\n    input wire [7:0] p_0, p_1, p_2, p_3, p_4, p_5, p_6, p_7,\n    input wire [7:0] p_8, p_9, p_10, p_11, p_12, p_13, p_14, p_15,\n    output reg [4:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [2:0] IDLE       = 3'd0;\n    localparam [2:0] PRECOMPUTE = 3'd1;\n    localparam [2:0] INIT_DP    = 3'd2;\n    localparam [2:0] DP_ITER    = 3'd3;\n    localparam [2:0] FINALIZE   = 3'd4;\n\n    // Constants\n    parameter MAX_N = 16;\n    parameter MAX_E = 8;\n    parameter INF = 5'b11111;\n\n    reg [2:0] state;\n    reg [7:0] p_arr [0:15];\n\n    // Precomputation regs\n    reg [4:0] fixed_count [0:16];\n    reg [3:0] total_odd, total_even;\n    reg [3:0] missing_odd, missing_even;\n    reg [3:0] odd_count, even_count;\n\n    // DP arrays\n    reg [4:0] dp_cur [0:8][0:1];\n    reg [4:0] dp_next [0:8][0:1];\n\n    // Counters\n    reg [4:0] i_counter;\n    reg [3:0] e_counter;\n    reg p_counter;\n\n    integer idx, e, m;  // Loop indices\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            done <= 1'b0;\n            result <= 5'd0;\n            state <= IDLE;\n\n            // Initialize arrays\n            for (m = 0; m <= 16; m = m + 1) fixed_count[m] <= 5'd0;\n            for (e = 0; e <= MAX_E; e = e + 1) begin\n                dp_cur[e][0] <= INF;\n                dp_cur[e][1] <= INF;\n                dp_next[e][0] <= INF;\n                dp_next[e][1] <= INF;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        // Store inputs\n                        p_arr[0]  <= p_0;  p_arr[1]  <= p_1;  p_arr[2]  <= p_2;  p_arr[3]  <= p_3;\n                        p_arr[4]  <= p_4;  p_arr[5]  <= p_5;  p_arr[6]  <= p_6;  p_arr[7]  <= p_7;\n                        p_arr[8]  <= p_8;  p_arr[9]  <= p_9;  p_arr[10] <= p_10; p_arr[11] <= p_11;\n                        p_arr[12] <= p_12; p_arr[13] <= p_13; p_arr[14] <= p_14; p_arr[15] <= p_15;\n                        state <= PRECOMPUTE;\n                    end\n                end\n\n                PRECOMPUTE: begin\n                    odd_count  <= 4'd0;\n                    even_count <= 4'd0;\n                    fixed_count[0] <= 5'd0;\n\n                    for (idx = 0; idx < MAX_N; idx = idx + 1) begin\n                        if (idx < n) begin\n                            if (p_arr[idx] != 8'd0) begin\n                                if (p_arr[idx][0]) odd_count  <= odd_count + 4'd1;\n                                else               even_count <= even_count + 4'd1;\n                                fixed_count[idx+1] <= fixed_count[idx] + 5'd1;\n                            end else begin\n                                fixed_count[idx+1] <= fixed_count[idx];\n                            end\n                        end else begin\n                            fixed_count[idx+1] <= fixed_count[idx];\n                        end\n                    end\n\n                    total_odd  <= (n + 6'd1) >> 1;\n                    total_even <= n >> 1;\n                    state <= INIT_DP;\n                end\n\n                INIT_DP: begin\n                    missing_odd  <= total_odd  - odd_count;\n                    missing_even <= total_even - even_count;\n\n                    // Reset DP arrays\n                    for (e = 0; e <= MAX_E; e = e + 1) begin\n                        dp_cur[e][0] <= INF;\n                        dp_cur[e][1] <= INF;\n                        dp_next[e][0] <= INF;\n                        dp_next[e][1] <= INF;\n                    end\n                    dp_cur[0][0] <= 5'd0;\n                    dp_cur[0][1] <= 5'd0;\n\n                    i_counter <= 5'd0;\n                    e_counter <= 4'd0;\n                    p_counter <= 1'b0;\n                    state <= DP_ITER;\n                end\n\n                DP_ITER: begin\n                    if (i_counter < n) begin\n                        if (e_counter > missing_even && p_counter) begin\n                            i_counter <= i_counter + 5'd1;\n                            e_counter <= 4'd0;\n                            p_counter <= 1'b0;\n\n                            // Shift DP state\n                            for (e = 0; e <= MAX_E; e = e + 1) begin\n                                dp_cur[e][0] <= dp_next[e][0];\n                                dp_cur[e][1] <= dp_next[e][1];\n                                dp_next[e][0] <= INF;\n                                dp_next[e][1] <= INF;\n                            end\n                        end else begin\n                            if (dp_cur[e_counter][p_counter] != INF) begin\n                                if (p_arr[i_counter] != 8'd0) begin\n                                    // Fixed element logic\n                                    if (dp_cur[e_counter][p_counter] + (p_counter != p_arr[i_counter][0]) < \n                                        dp_next[e_counter][p_arr[i_counter][0]]) begin\n                                        dp_next[e_counter][p_arr[i_counter][0]] <= dp_cur[e_counter][p_counter] + (p_counter != p_arr[i_counter][0]);\n                                    end\n                                end else begin\n                                    // Place even\n                                    if (e_counter < missing_even) begin\n                                        if (dp_cur[e_counter][p_counter] + (p_counter != 0) < \n                                            dp_next[e_counter + 1][0]) begin\n                                            dp_next[e_counter + 1][0] <= dp_cur[e_counter][p_counter] + (p_counter != 0);\n                                        end\n                                    end\n                                    // Place odd\n                                    if ((i_counter - fixed_count[i_counter] - e_counter) < missing_odd) begin\n                                        if (dp_cur[e_counter][p_counter] + (p_counter != 1) < \n                                            dp_next[e_counter][1]) begin\n                                            dp_next[e_counter][1] <= dp_cur[e_counter][p_counter] + (p_counter != 1);\n                                        end\n                                    end\n                                end\n                            end\n\n                            // Update counters\n                            if (p_counter) begin\n                                p_counter <= 1'b0;\n                                e_counter <= e_counter + 4'd1;\n                            end else begin\n                                p_counter <= 1'b1;\n                            end\n                        end\n                    end else begin\n                        state <= FINALIZE;\n                    end\n                end\n\n                FINALIZE: begin\n                    result <= (dp_cur[missing_even][0] < dp_cur[missing_even][1]) ? dp_cur[missing_even][0] : dp_cur[missing_even][1];\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule